                            <img src="@_avatarUrl" alt="Avatar" class="avatar-img" />
                        }
                        else
                        {
                            <div class="avatar-placeholder">No Image</div>
                        }
                    </div>
                    <div class="mt-2">
                        <label class="form-label small text-muted">Avatar URL</label>
                        <input type="url" class="form-control form-control-sm" @bind="_avatarUrl" />
                    </div>
                </div>
            </div>
        </div>

        <div class="d-flex gap-2 mt-3">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    };

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is null) return;
        _displayName = _savedProfile.DisplayName;
        _email = _savedProfile.Email;
        _avatarUrl = _savedProfile.AvatarUrl;
        _bio = _savedProfile.Bio;
    }

    // --- Notifications ---

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h3>Notifications</h3>
        <p class="text-muted">Choose how you want to be notified</p>
        <hr />

        <div class="mb-4">
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                <label class="form-check-label" for="emailNotif">
                    <strong>Email Notifications</strong>
                    <br /><small class="text-muted">Receive notifications via email</small>
                </label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                <label class="form-check-label" for="pushNotif">
                    <strong>Push Notifications</strong>
                    <br /><small class="text-muted">Receive push notifications in your browser</small>
                </label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">
                    <strong>Weekly Digest</strong>
                    <br /><small class="text-muted">Receive a weekly summary of activity</small>
                </label>
            </div>
        </div>

        <h5>Muted Channels</h5>
        <p class="text-muted small">Select channels to mute notifications from</p>
        <div class="row">
            @foreach (var channel in _allChannels)
            {
                var channelId = $"ch-{channel}";
                <div class="col-md-4 mb-2">
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="@channelId"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                        <label class="form-check-label" for="@channelId">#@channel</label>
                    </div>
                </div>
            }
        </div>

        <div class="mt-4">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    };

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, [.. _mutedChannels]);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // --- Security ---

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h3>Security</h3>
        <p class="text-muted">Manage your account security</p>
        <hr />

        <!-- Change Password -->
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center settings-expandable"
                 @onclick="() => _showChangePassword = !_showChangePassword"
                 role="button">
                <span class="fw-semibold">Change Password</span>
                <span class="expand-icon">@(_showChangePassword ? "▲" : "▼")</span>
            </div>
            @if (_showChangePassword)
            {
                <div class="card-body">
                    <div class="row">
                        <div class="col-md-6">
                            <div class="mb-3">
                                <label class="form-label">Current Password</label>
                                <input type="password" class="form-control" @bind="_currentPassword" />
                            </div>
                            <div class="mb-3">
                                <label class="form-label">New Password</label>
                                <input type="password" class="form-control" @bind="_newPassword" />
                            </div>
                            <div class="mb-3">
                                <label class="form-label">Confirm New Password</label>
                                <input type="password" class="form-control" @bind="_confirmPassword" />
                            </div>
                            <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                        </div>
                    </div>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled"
                           id="twoFactor" />
                </div>
            </div>
        </div>

        <!-- Active Sessions -->
        <h5>Active Sessions</h5>
        @if (_security?.LastPasswordChange is not null)
        {
            <p class="text-muted small">Last password change: @_security.LastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
        }

        @if (_security?.Sessions is { Count: > 0 })
        {
            <div class="table-responsive">
                <table class="table table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _security.Sessions)
                        {
                            var isCurrent = session == _security.Sessions[0];
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isCurrent)
                                    {
                                        <span class="badge bg-info ms-2">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (!isCurrent)
                                    {
                                        <button class="btn btn-outline-danger btn-sm"
                                                @onclick="() => RequestRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }
        else
        {
            <p class="text-muted">No active sessions found.</p>
        }
    };

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", isError: true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", isError: true);
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _showChangePassword = false;
        _security = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _security = await SettingsService.GetSecuritySettingsAsync();
        }
        _showRevokeDialog = false;
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    // --- Appearance ---

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <h3>Appearance</h3>
        <p class="text-muted">Customize the look and feel</p>
        <hr />

        <div class="row">
            <div class="col-md-6">
                <!-- Theme -->
                <div class="mb-4">
                    <label class="form-label fw-semibold">Theme</label>
                    <div>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            var themeId = $"theme-{theme}";
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="theme" id="@themeId"
                                       value="@theme" checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@themeId">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <label class="form-label fw-semibold">Font Size</label>
                    <div>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            var sizeId = $"fs-{size}";
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize" id="@sizeId"
                                       value="@size" checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@sizeId">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <label class="form-label fw-semibold">Language</label>
                    <select class="form-select" @bind="_language">
                        @foreach (var lang in _availableLanguages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">
                            <strong>Compact Mode</strong>
                            <br /><small class="text-muted">Reduce spacing and padding throughout the UI</small>
                        </label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>

            <!-- Live Preview -->
            <div class="col-md-6">
                <label class="form-label fw-semibold">Live Preview</label>
                <div class="preview-panel @GetPreviewClasses()">
                    <div class="preview-header">
                        <span class="preview-title">Dashboard</span>
                        <span class="preview-badge">3 notifications</span>
                    </div>
                    <div class="preview-body">
                        <p class="preview-text">This is a preview of how your settings will look. The theme, font size, and compact mode changes are reflected here.</p>
                        <div class="preview-card">
                            <strong>Sample Card</strong>
                            <p class="preview-text mb-0">Card content with your selected appearance settings applied.</p>
                        </div>
                        <div class="preview-actions">
                            <span class="preview-btn-primary">Primary</span>
                            <span class="preview-btn-secondary">Secondary</span>
                        </div>
                    </div>
                    <div class="preview-footer">
                        Language: @_language
                    </div>
                </div>
            </div>
        </div>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_fontSize.ToLowerInvariant()}");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(' ', classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }
}

